function glassCss(opts){
  opts=opts||{};
  var blur=opts.blur!=null?opts.blur:12;
  var alpha=opts.alpha!=null?opts.alpha:0.18;
  var radius=opts.radius!=null?opts.radius:16;
  var border=opts.border!=null?opts.border:0.35;
  var saturate=opts.saturate!=null?opts.saturate:160;
  var L=[];
  L.push('.glass {');
  L.push('  background: rgba(255, 255, 255, '+alpha+');');
  L.push('  backdrop-filter: blur('+blur+'px) saturate('+saturate+'%);');
  L.push('  -webkit-backdrop-filter: blur('+blur+'px) saturate('+saturate+'%);');
  L.push('  border-radius: '+radius+'px;');
  L.push('  border: 1px solid rgba(255, 255, 255, '+border+');');
  L.push('}');
  return L.join('\n');
}

var EXPORTS={glassCss:glassCss};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BlurForgePure = EXPORTS; }
